-- V12: DB 데이터 정합성 수정 + 봄빛 축제 부스 위치 데이터 추가
-- 1. 고아 부스(하하하 트럭, festival_id=NULL) 및 관련 위치 데이터 삭제
-- 2. queue_number=0 중복 수정 (ROW_NUMBER 기반 재채번)
-- 3. 봄빛 대학 축제 2026 전체 부스 위치 데이터 추가 (DAY/NIGHT/FOOD_TRUCK × 3일)

-- ============================================================
-- Step 1: 고아 부스 삭제
-- ============================================================
DELETE FROM booth_locations WHERE booth_id = 'b41c4557-6a54-4722-8b3b-48465e174cff';
DELETE FROM booths WHERE id = 'b41c4557-6a54-4722-8b3b-48465e174cff';

-- ============================================================
-- Step 2: queue_number=0 중복 재채번 (festival_id 관계없이 전체)
-- ============================================================
UPDATE waitings w
SET queue_number = sub.rn
FROM (
    SELECT id,
           ROW_NUMBER() OVER (PARTITION BY booth_id ORDER BY registered_at) AS rn
    FROM waitings
    WHERE queue_number = 0
) sub
WHERE w.id = sub.id;

-- ============================================================
